"""Make The String Great — stack, popping case-flipped pairs.

Time: O(n)   Space: O(n)
"""


class Solution:
    def makeGood(self, s: str) -> str:
        stack = []
        for ch in s:
            if stack and stack[-1] != ch and stack[-1].lower() == ch.lower():
                stack.pop()
            else:
                stack.append(ch)
        return "".join(stack)
